{"content":"import unittest
from functools import lru_cache
from itertools import combinations, product

from book_store import total


class BookStoreTest(unittest.TestCase):
    def test_empty_basket(self):
        self.assertEqual(total([]), 0)

    def test_each_discount(self):
        for size, expected in enumerate((800, 1520, 2160, 2560, 3000), 1):
            with self.subTest(size=size):
                self.assertEqual(total(list(range(1, size + 1))), expected)

    def test_repeated_title_has_no_discount(self):
        self.assertEqual(total([1, 1, 1]), 2400)

    def test_duplicate_outside_discounted_set(self):
        self.assertEqual(total([1, 1, 2, 3]), 2960)

    def test_two_groups_of_four_beat_five_and_three(self):
        self.assertEqual(total([1, 1, 2, 2, 3, 3, 4, 5]), 5120)

    def test_multiple_full_sets(self):
        self.assertEqual(total([1, 2, 3, 4, 5] * 2), 6000)

    def test_large_basket(self):
        self.assertEqual(total([1] * 1500 + [2]), 1499 * 800 + 1520)

    def test_does_not_modify_basket(self):
        basket = [5, 1, 3, 1, 2, 4, 2, 3]
        original = basket.copy()
        self.assertEqual(total(basket), 5120)
        self.assertEqual(basket, original)

    def test_all_small_baskets_against_exhaustive_grouping(self):
        # Independent oracle: try every subset of titles, not just the most
        # numerous titles used by the production algorithm.
        set_prices = (0, 800, 1520, 2160, 2560, 3000)

        @lru_cache(maxsize=None)
        def exhaustive(counts):
            available = [index for index, count in enumerate(counts) if count]
            if not available:
                return 0
            best = sum(counts) * 800
            for size in range(1, len(available) + 1):
                for group in combinations(available, size):
                    remaining = list(counts)
                    for index in group:
                        remaining[index] -= 1
                    best = min(best, set_prices[size] + exhaustive(tuple(remaining)))
            return best

        for counts in product(range(4), repeat=5):
            basket = [title for title, count in enumerate(counts)
                      for _ in range(count)]
            with self.subTest(counts=counts):
                self.assertEqual(total(basket), exhaustive(counts))


if __name__ == "__main__":
    unittest.main()
